package br.com.equilibra.cashflow.api;
import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.constraints.NotNull; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import br.com.equilibra.cashflow.application.CashFlowProjectionService;
@RestController @RequestMapping("/cash-flow") @Tag(name="Cash Flow") @SecurityRequirement(name="bearerAuth") public class CashFlowController { private final CashFlowProjectionService service; public CashFlowController(CashFlowProjectionService s){service=s;} @Operation(summary="Read-only cash flow projection") @GetMapping("/projection") public CashFlowDtos.Response project(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to,@RequestParam(required=false) List<String> accountIds){return service.project(from,to,accountIds);} }
